## Rule-based AI for Persian Rails Empire. Levels 1–3.
extends RefCounted

var level: int = 2
var rng: RandomNumberGenerator = RandomNumberGenerator.new()


func _init(p_level: int = 2) -> void:
	level = clampi(p_level, 1, 3)
	rng.randomize()


func choose(rules) -> Dictionary:
	var acts: Array = rules.legal_actions()
	if acts.is_empty():
		return {"type": "draw_trains"}
	var pi: int = rules.current
	var p: Dictionary = rules.players[pi]
	# Score claim actions by ticket progress and route value
	var claims: Array = []
	for a in acts:
		if str(a.type) != "claim":
			continue
		var route = rules.route_by_id(str(a.route))
		var score := float(rules.route_score(route))
		# ticket synergy
		for t in p.tickets:
			if str(t.from) == str(route.from) or str(t.from) == str(route.to) \
					or str(t.to) == str(route.from) or str(t.to) == str(route.to):
				score += float(t.points) * 0.35
			# prefer edges that sit on incomplete tickets
			if not rules.connected(pi, str(t.from), str(t.to)):
				score += 1.5
		# scarcity / blocking: prefer shorter early at low level
		if level == 1:
			score += rng.randf() * 3.0
			score -= float(route.length) * 0.2
		elif level == 2:
			score += rng.randf() * 1.5
		else:
			score -= float(rules.cost_for_route(route)) * 0.1
			if int(p.wagons) <= 8:
				score += float(rules.route_score(route)) * 0.5
		claims.append({"act": a, "score": score})
	claims.sort_custom(func(a, b): return a.score > b.score)

	var should_claim := false
	if claims.size():
		if level == 1:
			should_claim = rng.randf() < 0.45
		elif level == 2:
			should_claim = rng.randf() < 0.7 or claims[0].score > 6.0
		else:
			should_claim = claims[0].score > 4.0 or int(p.hand.size()) >= 6
	if should_claim and claims.size():
		return claims[0].act

	# draw tickets if few left and pile exists
	for a in acts:
		if str(a.type) == "draw_tickets" and p.tickets.size() < (1 if level == 1 else 2):
			if level >= 2 and rng.randf() < 0.25:
				return {"type": "draw_tickets"}

	# otherwise draw trains — prefer face-up matching ticket colors / needed
	var need: Dictionary = {}
	for r in rules.routes:
		if rules.claimed.has(str(r.id)):
			continue
		var col := str(r.color)
		if col != "gray":
			need[col] = int(need.get(col, 0)) + int(r.length)
	var picks: Array = []
	var used := {}
	for i in range(rules.face_up.size()):
		if picks.size() >= 2:
			break
		var c := str(rules.face_up[i])
		if c == rules.LOCO and level >= 2:
			picks.append(i)
			used[i] = true
			break
		if need.has(c) and not used.has(i):
			picks.append(i)
			used[i] = true
	while picks.size() < 2:
		picks.append("deck")
	return {"type": "draw_trains", "picks": picks}

## Loads shipped textures (parchment, wood, felt, UI) once.
extends RefCounted

const DIR := "res://arena/persian_rails/textures/"

static var _cache: Dictionary = {}
static var _style_cache: Dictionary = {}


static func tex(name: String) -> Texture2D:
	if _cache.has(name):
		return _cache[name]
	var path := DIR + name
	var t: Texture2D = null
	if ResourceLoader.exists(path):
		var res = load(path)
		if res is Texture2D:
			t = res
		elif res is Image:
			t = ImageTexture.create_from_image(res)
	_cache[name] = t
	return t


static func mat_tex(name: String, color: Color = Color.WHITE, rough: float = 0.9, uv_scale: float = 1.0) -> StandardMaterial3D:
	var m := StandardMaterial3D.new()
	m.albedo_color = color
	m.roughness = rough
	var t := tex(name)
	if t:
		m.albedo_texture = t
		m.uv1_scale = Vector3(uv_scale, uv_scale, uv_scale)
	return m


static func style_tex(name: String, pad: float = 12.0, expand: float = 18.0) -> StyleBoxTexture:
	# Cache StyleBoxes — recreating them every HUD paint exhausts WebGL on long hands.
	var slice := maxf(expand, _min_slice_for(name))
	var key := "%s|%.2f|%.2f" % [name, pad, slice]
	if _style_cache.has(key):
		return _style_cache[key]
	var st := StyleBoxTexture.new()
	var t := tex(name)
	if t:
		st.texture = t
	st.texture_margin_left = slice
	st.texture_margin_right = slice
	st.texture_margin_top = slice
	st.texture_margin_bottom = slice
	st.content_margin_left = pad
	st.content_margin_right = pad
	st.content_margin_top = pad * 0.7
	st.content_margin_bottom = pad * 0.7
	_style_cache[key] = st
	return st


static func _min_slice_for(name: String) -> float:
	if name.begins_with("btn_"):
		return 26.0
	if name.begins_with("panel_fantasy"):
		return 40.0
	if name.begins_with("panel_top"):
		return 32.0
	if name.begins_with("card_frame"):
		return 26.0
	return 18.0


static func btn_tex(kind: String, pad: float = 10.0, state: String = "normal") -> StyleBoxTexture:
	var base := "btn_primary"
	match kind:
		"accent":
			base = "btn_accent"
		"secondary", "ghost":
			base = "btn_secondary"
		_:
			base = "btn_primary"
	var name := base + ".png"
	if state == "hover" and tex(base + "_hover.png") != null:
		name = base + "_hover.png"
	elif state == "pressed" and tex(base + "_pressed.png") != null:
		name = base + "_pressed.png"
	elif state == "disabled":
		name = "btn_secondary.png"
	return style_tex(name, pad, 26.0)

## Shared Vazirmatn UI font (Farsi digits) for HUD and Label3D.
extends RefCounted

const REGULAR := "res://arena/persian_rails/fonts/Vazirmatn-UI-FD-Regular.ttf"
const BOLD := "res://arena/persian_rails/fonts/Vazirmatn-UI-FD-Bold.ttf"

static var _regular: FontFile
static var _bold: FontFile


static func regular() -> Font:
	if _regular == null:
		_regular = _load(REGULAR)
	return _regular


static func bold() -> Font:
	if _bold == null:
		_bold = _load(BOLD)
	if _bold == null:
		return regular()
	return _bold


static func _load(path: String) -> FontFile:
	# Prefer the imported resource; fall back to dynamic load (web/pack).
	if ResourceLoader.exists(path):
		var res = load(path)
		if res is FontFile:
			return res as FontFile
		if res is Font:
			var wrap := FontFile.new()
			# Imported DynamicFontVariation / FontFile already usable via Font API.
			return res as FontFile
	var f := FontFile.new()
	var err := f.load_dynamic_font(path)
	if err != OK:
		push_warning("Persian font missing (%s): %s" % [str(err), path])
		return null
	return f


static func apply(control: Control, size: int = 16, use_bold: bool = false) -> void:
	var font := bold() if use_bold else regular()
	if font:
		control.add_theme_font_override("font", font)
	control.add_theme_font_size_override("font_size", size)
	control.layout_direction = Control.LAYOUT_DIRECTION_RTL


static func apply_label3d(label: Label3D, size: int = 48) -> void:
	var font := regular()
	if font:
		label.font = font
	label.font_size = size
	label.text_direction = TextServer.DIRECTION_RTL

## Persian Rails Empire — production 2.5D board game vs AI.
extends Node3D

signal arena_event(json: String)

const Rules = preload("res://arena/persian_rails/rules.gd")
const AIScript = preload("res://arena/persian_rails/ai.gd")
const MapView = preload("res://arena/persian_rails/map_view.gd")
const Hud = preload("res://arena/persian_rails/hud.gd")
const Tutorial = preload("res://arena/persian_rails/tutorial.gd")
const Models = preload("res://arena/persian_rails/models.gd")
const Fonts = preload("res://arena/persian_rails/fonts.gd")
const ThemeX = preload("res://arena/persian_rails/theme.gd")

var rules = Rules.new()
var ai = AIScript.new(2)
var models = Models.new()
var params := {
	"level": 2, "ai_count": 1, "wagons": 45,
	"player_name": "تو", "opponent_name": "حریف هوشمند",
}
var started := false
var over := false
var claim_mode := false
var _map: Node3D
var _hud
var _tutorial
var _camera: Camera3D
var _cam_yaw := 0.1
var _cam_pitch := deg_to_rad(66.0)
var _cam_dist := 18.0
var _target := Vector3(0.0, 0.0, -0.6)
var _drag := false
var _drag_mode := "pan"
var _headless := false
var _standalone := false
var _ai_busy := false
var _touches := {}
var _pinch_dist := 0.0
var _env: WorldEnvironment


func _ready() -> void:
	_headless = DisplayServer.get_name() == "headless"
	_install_persian_font()
	_fit_camera_defaults()
	rules.load_data()
	_build_world()
	_hud = Hud.new()
	_hud.name = "HUD"
	add_child(_hud)
	_hud.action.connect(_on_hud)
	_tutorial = Tutorial.new()
	_tutorial.name = "Tutorial"
	add_child(_tutorial)
	_tutorial.bind_hud(_hud)
	_tutorial.finished.connect(_on_tutorial_finished)
	_tutorial.practice_claim.connect(_on_tutorial_practice_claim)
	get_viewport().size_changed.connect(_place_camera)
	_standalone = get_tree().current_scene == self
	if _standalone:
		call_deferred("arena_start", _params_from_page())
	_emit({"type": "ready", "game": "persian-rails"})


func _install_persian_font() -> void:
	var font := Fonts.regular()
	if font == null:
		return
	var theme := Theme.new()
	theme.default_font = font
	theme.default_font_size = 18
	theme.set_font("font", "Label", font)
	theme.set_font("font", "Button", Fonts.bold() if Fonts.bold() else font)
	get_tree().root.theme = theme


func _fit_camera_defaults() -> void:
	var vp := get_viewport().get_visible_rect().size
	if vp.x <= 0.0:
		return
	# Slightly closer + flatter so Iran fills the free band between HUD chrome.
	if vp.x < 720.0:
		_cam_dist = 14.2
		_cam_pitch = deg_to_rad(62.0)
		_cam_yaw = 0.04
	else:
		_cam_dist = 14.6
		_cam_pitch = deg_to_rad(58.0)


func arena_start(p: Dictionary = {}) -> void:
	for k in p:
		params[k] = p[k]
	ai = AIScript.new(int(params.get("level", 2)))
	rules.load_data()
	rules.start(
		str(params.get("player_name", "تو")),
		int(params.get("ai_count", 1)),
		int(params.get("wagons", 45)),
		int(params.get("seed", 0))
	)
	started = true
	over = false
	claim_mode = false
	_target = Vector3(0.0, 0.0, -0.6)
	if _map:
		_map.setup(rules, models)
		if _map.has_method("set_claim_glow"):
			_map.set_claim_glow(false)
	if _hud:
		_hud.hide_modal()
		_hud.set_strings(rules.fa)
		_hud.set_claim_mode(false)
		_refresh_ui()
	if _tutorial:
		_tutorial.set_strings(rules.fa)
		_tutorial.bind_hud(_hud)
	_place_camera()
	_emit({"type": "started", "game": "persian-rails", "level": int(params.get("level", 2))})
	var show_tut := _should_show_tutorial()
	# One-shot flags so a later restart does not keep forcing/skipping the coach.
	params.erase("force_tutorial")
	params.erase("skip_tutorial")
	if show_tut:
		_tutorial.begin()
		_refresh_ui()
	else:
		if _hud and _hud.has_method("flash_turn"):
			_hud.flash_turn(str(rules.fa.get("your_turn", "نوبت توئه")))
		_maybe_ai()


func arena_stop() -> void:
	started = false
	over = true


func arena_state() -> Dictionary:
	return rules.snapshot() if started else {}


func _params_from_page() -> Dictionary:
	var out := {}
	if not OS.has_feature("web"):
		return out
	var q = JavaScriptBridge.eval("window.location.search", true)
	if typeof(q) != TYPE_STRING:
		return out
	for pair in str(q).trim_prefix("?").split("&", false):
		var kv := pair.split("=")
		if kv.size() == 2:
			out[kv[0].uri_decode()] = kv[1].uri_decode()
	if out.has("level"):
		out.level = int(out.level)
	if out.has("ai_count"):
		out.ai_count = int(out.ai_count)
	if out.has("wagons"):
		out.wagons = int(out.wagons)
	return out


func _build_world() -> void:
	var sun := DirectionalLight3D.new()
	sun.rotation_degrees = Vector3(-52, 38, 0)
	sun.light_energy = 1.35
	sun.light_color = Color("fff1dc")
	add_child(sun)
	var fill := DirectionalLight3D.new()
	fill.rotation_degrees = Vector3(-20, -150, 0)
	fill.light_energy = 0.4
	fill.light_color = Color("b7d7ef")
	add_child(fill)
	var rim := DirectionalLight3D.new()
	rim.rotation_degrees = Vector3(-10, 120, 0)
	rim.light_energy = 0.22
	rim.light_color = Color("ffe0b0")
	add_child(rim)

	_env = WorldEnvironment.new()
	var env := Environment.new()
	env.background_mode = Environment.BG_COLOR
	env.background_color = ThemeX.SKY_TOP
	env.ambient_light_source = Environment.AMBIENT_SOURCE_COLOR
	env.ambient_light_color = Color("ffe6cc")
	env.ambient_light_energy = 0.68
	env.tonemap_mode = Environment.TONE_MAPPER_FILMIC
	env.adjustment_enabled = true
	env.adjustment_saturation = 1.1
	env.adjustment_contrast = 1.05
	_env.environment = env
	add_child(_env)

	# Gradient sky cards (cheap, readable backdrop)
	_sky_card(Vector3(0, 8, -18), Vector2(48, 22), ThemeX.SKY_TOP)
	_sky_card(Vector3(0, -1.2, -18), Vector2(48, 10), ThemeX.SKY_BOT)

	_camera = Camera3D.new()
	_camera.current = true
	_camera.fov = 40.0
	_camera.near = 0.05
	_camera.far = 140.0
	add_child(_camera)
	_place_camera()

	_map = MapView.new()
	_map.name = "Map"
	add_child(_map)
	_map.city_tapped.connect(_on_city)
	_map.route_tapped.connect(_on_route)


func _sky_card(pos: Vector3, size: Vector2, color: Color) -> void:
	var mi := MeshInstance3D.new()
	var q := QuadMesh.new()
	q.size = size
	mi.mesh = q
	var m := ThemeX.mat(color, 1.0)
	m.shading_mode = BaseMaterial3D.SHADING_MODE_UNSHADED
	mi.material_override = m
	mi.position = pos
	add_child(mi)


func _place_camera() -> void:
	if _camera == null:
		return
	var look := _target
	var vp := get_viewport().get_visible_rect().size
	if vp.y > 0.0 and _hud and _hud.has_method("chrome_insets"):
		var insets: Vector2 = _hud.chrome_insets()
		var top_frac := insets.x / vp.y
		var bot_frac := insets.y / vp.y
		var mid := (top_frac + (1.0 - bot_frac)) * 0.5
		var bias := (0.5 - mid) * _cam_dist * 0.6
		look += Vector3(0, 0, bias)
	var offset := Vector3(
		sin(_cam_yaw) * cos(_cam_pitch),
		sin(_cam_pitch),
		cos(_cam_yaw) * cos(_cam_pitch)
	) * _cam_dist
	_camera.position = look + offset
	_camera.look_at(look, Vector3.UP)
	_camera.fov = 38.0 if vp.x < 720.0 else 40.0
	if _map and _map.has_method("set_label_lod"):
		_map.set_label_lod(_cam_dist)


func _should_show_tutorial() -> bool:
	## Coach runs every time the player enters a match (unless a test opts out).
	if _tutorial == null:
		return false
	if bool(params.get("skip_tutorial", false)):
		return false
	return true


func _on_tutorial_finished(_skipped: bool) -> void:
	claim_mode = false
	if _hud:
		_hud.set_claim_mode(false)
		if _hud.has_method("pulse_action"):
			_hud.pulse_action("", false)
		if _hud.has_method("flash_turn"):
			_hud.flash_turn(str(rules.fa.get("your_turn", "نوبت توئه")))
	if _map and _map.has_method("set_claim_glow"):
		_map.set_claim_glow(false)
	_refresh_ui()
	_maybe_ai()


func _on_tutorial_practice_claim(on: bool) -> void:
	claim_mode = on
	if _hud:
		_hud.set_claim_mode(on)
	if _map and _map.has_method("set_claim_glow"):
		_map.set_claim_glow(on)
	if on and _hud:
		_hud.toast(str(rules.fa.get("tut_route_hint", rules.fa.get("claim_hint", "یک مسیر آزاد لمس کن"))))


func _unhandled_input(event: InputEvent) -> void:
	if event is InputEventMouseButton:
		var mb := event as InputEventMouseButton
		if mb.button_index == MOUSE_BUTTON_LEFT:
			_drag = mb.pressed
			_drag_mode = "pan"
		elif mb.button_index == MOUSE_BUTTON_RIGHT or mb.button_index == MOUSE_BUTTON_MIDDLE:
			_drag = mb.pressed
			_drag_mode = "orbit"
		elif mb.button_index == MOUSE_BUTTON_WHEEL_UP:
			_cam_dist = maxf(9.5, _cam_dist - 0.65)
			_place_camera()
			if _tutorial and _tutorial.is_blocking():
				_tutorial.notify_zoom()
		elif mb.button_index == MOUSE_BUTTON_WHEEL_DOWN:
			_cam_dist = minf(24.0, _cam_dist + 0.65)
			_place_camera()
			if _tutorial and _tutorial.is_blocking():
				_tutorial.notify_zoom()
	elif event is InputEventMouseMotion and _drag:
		var mm := event as InputEventMouseMotion
		if _drag_mode == "orbit":
			_cam_yaw -= mm.relative.x * 0.0045
			_cam_pitch = clampf(_cam_pitch - mm.relative.y * 0.0035, deg_to_rad(48.0), deg_to_rad(78.0))
			if _tutorial and _tutorial.is_blocking():
				_tutorial.notify_pan(mm.relative.length())
		else:
			_pan_by(mm.relative)
		_place_camera()
	elif event is InputEventScreenTouch:
		var st := event as InputEventScreenTouch
		if st.pressed:
			_touches[st.index] = st.position
			if _touches.size() == 1:
				_drag = true
				_drag_mode = "pan"
			elif _touches.size() == 2:
				_drag = false
				var pts: Array = _touches.values()
				_pinch_dist = pts[0].distance_to(pts[1])
		else:
			_touches.erase(st.index)
			_drag = _touches.size() == 1
			_drag_mode = "pan"
	elif event is InputEventScreenDrag:
		var sd := event as InputEventScreenDrag
		_touches[sd.index] = sd.position
		if _touches.size() == 2:
			var pts2: Array = _touches.values()
			var d: float = pts2[0].distance_to(pts2[1])
			if _pinch_dist > 0.0:
				_cam_dist = clampf(_cam_dist * (_pinch_dist / maxf(d, 1.0)), 9.5, 24.0)
				_place_camera()
				if _tutorial and _tutorial.is_blocking():
					_tutorial.notify_zoom()
			_pinch_dist = d
		elif _drag:
			_pan_by(sd.relative)
			_place_camera()


func _pan_by(rel: Vector2) -> void:
	var sens := _cam_dist * 0.0017
	var right := Vector3(cos(_cam_yaw), 0, -sin(_cam_yaw))
	var forward := Vector3(sin(_cam_yaw), 0, cos(_cam_yaw))
	_target -= right * rel.x * sens
	_target += forward * rel.y * sens
	_target.x = clampf(_target.x, -6.0, 6.0)
	_target.z = clampf(_target.z, -6.5, 6.5)
	if _tutorial and _tutorial.is_blocking():
		_tutorial.notify_pan(rel.length())


func _on_hud(kind: String, _data: Dictionary) -> void:
	if _tutorial and _tutorial.is_blocking():
		if _tutorial.notify_action(kind):
			return
		# Block unrelated actions while the coach is teaching a specific tap.
		if kind != "restart":
			return
	if not started or over:
		if kind == "restart":
			arena_start(params)
		return
	if rules.players[rules.current].is_ai:
		return
	match kind:
		"leave":
			# Host shell handles returning to the lobby.
			_emit({"type": "leave", "game": "persian-rails"})
		"draw_trains":
			_do_action({"type": "draw_trains"})
		"draw_tickets":
			_do_action({"type": "draw_tickets"})
		"claim_mode":
			claim_mode = true
			_hud.set_claim_mode(true)
			if _map.has_method("set_claim_glow"):
				_map.set_claim_glow(true)
			_hud.toast(str(rules.fa.get("claim_hint", "یک مسیر آزاد روی نقشه لمس کن")))
		"restart":
			arena_start(params)


func _on_city(city_id: String) -> void:
	if _tutorial and _tutorial.is_blocking() and _tutorial.current_kind() == "tap_route":
		return
	var c = rules.city_by_id(city_id)
	if c.is_empty():
		return
	_hud.toast("%s — %s" % [str(c.name_fa), str(c.name_en)])
	_map.highlight_city(city_id, true)


func _on_route(route_id: String) -> void:
	if _tutorial and _tutorial.is_blocking():
		if _tutorial.notify_route(route_id):
			if _map.has_method("highlight_route"):
				_map.highlight_route(route_id, true)
			_hud.toast(str(rules.fa.get("tut_route_done", "آفرین! تو مسیر رو انتخاب کردی")))
			return
		return
	if not started or over or rules.players[rules.current].is_ai:
		return
	if not claim_mode:
		var r = rules.route_by_id(route_id)
		if _map.has_method("highlight_route"):
			_map.highlight_route(route_id, true)
		_hud.toast("مسیر %s → %s · %d واگن" % [
			rules.city_by_id(str(r.from)).get("name_fa", "?"),
			rules.city_by_id(str(r.to)).get("name_fa", "?"),
			rules.cost_for_route(r)])
		return
	claim_mode = false
	if _hud:
		_hud.set_claim_mode(false)
	if _map.has_method("set_claim_glow"):
		_map.set_claim_glow(false)
	_do_action({"type": "claim", "route": route_id})


func _do_action(action: Dictionary) -> void:
	var ev := rules.apply(action)
	if not ev.get("ok", false):
		var err := str(ev.get("error", ""))
		match err:
			"need_cards":
				_hud.toast(str(rules.fa.get("need_cards", "کارت کافی نداری")))
			"route_unavailable":
				_hud.toast(str(rules.fa.get("route_taken", "این مسیر گرفته شده")))
			_:
				_hud.toast("نشد انجام بشه")
		return
	_emit({"type": "move", "action": action.get("type"), "player": 0})
	_after_move()


func _after_move() -> void:
	_map.refresh_claims()
	_refresh_ui()
	if rules.over:
		_finish()
	else:
		_maybe_ai()


func _maybe_ai() -> void:
	if not started or rules.over or _ai_busy:
		return
	if _tutorial and _tutorial.is_blocking():
		return
	if not rules.players[rules.current].is_ai:
		_refresh_ui()
		return
	_ai_busy = true
	_refresh_ui()
	if _headless:
		_run_ai_burst()
	else:
		get_tree().create_timer(0.55).timeout.connect(_run_ai_burst)


func _run_ai_burst() -> void:
	var guard := 0
	while started and not rules.over and rules.players[rules.current].is_ai and guard < 8:
		var act := ai.choose(rules)
		var ev := rules.apply(act)
		if not ev.get("ok", false):
			rules.apply({"type": "draw_trains"})
		_emit({"type": "move", "action": act.get("type"), "player": rules.current, "ai": true})
		guard += 1
		if not rules.players[rules.current].is_ai:
			break
	_ai_busy = false
	_map.refresh_claims()
	_refresh_ui()
	if rules.over:
		_finish()
	elif rules.players[rules.current].is_ai:
		_maybe_ai()


func _finish() -> void:
	over = true
	var res := rules.final_result()
	res["level"] = int(params.get("level", 2))
	# Shell-hosted matches show the Godot shell result card (with rating).
	# Standalone / legacy embeds keep the in-HUD modal.
	if _standalone and _hud:
		_hud.show_result(res)
	_emit(res)


func _refresh_ui() -> void:
	if _hud == null:
		return
	var human_turn: bool = started and (not rules.over) and (not bool(rules.players[rules.current].get("is_ai", false)))
	_hud.show_state(rules, human_turn)


func _emit(obj: Dictionary) -> void:
	var json := JSON.stringify(obj)
	arena_event.emit(json)
	if _standalone and OS.has_feature("web"):
		JavaScriptBridge.eval("window.parent && window.parent.postMessage({arena: %s}, '*')" % json, true)

## Clean Iran board — seas/lakes, tuned 3D scales, quieter styling.
extends Node3D

signal city_tapped(city_id: String)
signal route_tapped(route_id: String)

const Fonts = preload("res://arena/persian_rails/fonts.gd")
const ThemeX = preload("res://arena/persian_rails/theme.gd")
const Assets = preload("res://arena/persian_rails/assets.gd")

# Clean board scales — even corridors, gems that don't eat into rails.
const CITY_GEM := 0.10
const CITY_RING := 0.17
const CITY_BASE := 0.14
const RAIL_W := 0.135
const RAIL_H := 0.038
const TIE_W := 0.24
const BAR_W := 0.022
const LABEL_Y := 0.38
const ROUTE_INSET := 0.42
const PARALLEL_OFFSET := 0.20
const SEG_GAP := 0.11
const MIN_SEG := 0.28

var rules
var models
var city_nodes: Dictionary = {}
var route_nodes: Dictionary = {}
var wagon_nodes: Dictionary = {}
var route_mats: Dictionary = {}
var _board: Node3D
var _claim_glow := false
var _pulse_t := 0.0
var _compact_labels := false
var _label_nodes: Array = []
var _geo: Dictionary = {}
var _claims_fp := ""
var _widened_routes: Dictionary = {}


func setup(p_rules, p_models) -> void:
	rules = p_rules
	models = p_models
	_geo = _load_geo()
	_claims_fp = ""
	_widened_routes.clear()
	var vp := get_viewport().get_visible_rect().size if get_viewport() else Vector2(390, 700)
	var dens: Dictionary = ThemeX.density(vp)
	_compact_labels = bool(dens.get("phone", true)) or bool(dens.get("compact", true))
	_build_board()
	set_label_lod(16.0 if _compact_labels else 12.0)


func _load_geo() -> Dictionary:
	# Prefer full geography (real Iran outline + waters); fall back to waters.json.
	for path in ["res://arena/persian_rails/data/geography.json", "res://arena/persian_rails/data/waters.json"]:
		if not FileAccess.file_exists(path):
			continue
		var f := FileAccess.open(path, FileAccess.READ)
		if f == null:
			continue
		var data = JSON.parse_string(f.get_as_text())
		if typeof(data) == TYPE_DICTIONARY:
			return data
	return {"seas": [], "lakes": [], "iran_outline": []}


func _pts(raw: Array, max_pts: int = 96) -> Array:
	var out: Array = []
	for p in raw:
		if typeof(p) == TYPE_ARRAY and p.size() >= 2:
			out.append(Vector2(float(p[0]), float(p[1])))
		elif typeof(p) == TYPE_VECTOR2:
			out.append(p)
	return _decimate(out, max_pts)


func _decimate(pts: Array, max_pts: int) -> Array:
	if pts.size() <= max_pts or max_pts < 6:
		return pts
	var out: Array = []
	var step := float(pts.size()) / float(max_pts)
	var i := 0.0
	while int(i) < pts.size() and out.size() < max_pts:
		out.append(pts[int(i)])
		i += step
	return out


func _iran_outline() -> Array:
	var pts := _pts(_geo.get("iran_outline", []), 160)
	if pts.size() >= 8:
		return pts
	# Fallback schematic outline from theme.
	var fallback: Array = []
	for p in ThemeX.IRAN_OUTLINE:
		fallback.append(p)
	return fallback


func _process(delta: float) -> void:
	if not _claim_glow:
		return
	_pulse_t += delta
	var pulse := 0.4 + 0.5 * sin(_pulse_t * 3.2)
	for rid in route_mats.keys():
		if rules and rules.claimed.has(rid):
			continue
		var m: StandardMaterial3D = route_mats[rid]
		if m:
			m.emission_energy_multiplier = pulse * 0.55


func set_claim_glow(on: bool) -> void:
	_claim_glow = on
	_pulse_t = 0.0
	set_process(on)
	for rid in route_mats.keys():
		var m: StandardMaterial3D = route_mats[rid]
		if m == null:
			continue
		if on and rules and not rules.claimed.has(rid):
			m.emission_enabled = true
			m.emission = m.albedo_color.lightened(0.25)
			m.emission_energy_multiplier = 0.4
		else:
			m.emission_enabled = rules != null and rules.claimed.has(rid)
			if not m.emission_enabled:
				m.emission_energy_multiplier = 0.0


func set_label_lod(dist: float) -> void:
	var show := (not _compact_labels) or dist < 13.5
	for n in _label_nodes:
		if is_instance_valid(n):
			n.visible = show


func _build_board() -> void:
	for c in get_children():
		c.queue_free()
	city_nodes.clear()
	route_nodes.clear()
	wagon_nodes.clear()
	route_mats.clear()
	_label_nodes.clear()
	_board = Node3D.new()
	_board.name = "Board"
	add_child(_board)
	_add_table()
	# Seas under land (clean coasts); lakes on top of land (inland water).
	_add_parchment()
	_add_seas()
	_add_iran_land()
	_add_lakes()
	_add_region_washes()
	_add_ornament()
	for route in rules.routes:
		_add_route(route)
	for city in rules.cities:
		_add_city(city)


