	rbox.size = Vector3(0.30, 0.035, 0.46 if loco else 0.40)
	roof.mesh = rbox
	roof.material_override = trim
	roof.position.y = 0.23
	root.add_child(roof)
	for xz in [Vector2(-0.14, -0.16), Vector2(0.14, -0.16), Vector2(-0.14, 0.16), Vector2(0.14, 0.16)]:
		var wh := MeshInstance3D.new()
		var wc := CylinderMesh.new()
		wc.top_radius = 0.05
		wc.bottom_radius = 0.05
		wc.height = 0.045
		wh.mesh = wc
		wh.rotation_degrees = Vector3(0, 0, 90)
		wh.material_override = ThemeX.mat(Color("1a1a1a"), 0.55, 0.45)
		wh.position = Vector3(xz.x, 0.05, xz.y)
		root.add_child(wh)
	if loco:
		var nose := MeshInstance3D.new()
		var nbox := BoxMesh.new()
		nbox.size = Vector3(0.26, 0.11, 0.13)
		nose.mesh = nbox
		nose.material_override = body_mat
		nose.position = Vector3(0, 0.14, -0.32)
		root.add_child(nose)
		var funnel := MeshInstance3D.new()
		var fc := CylinderMesh.new()
		fc.top_radius = 0.038
		fc.bottom_radius = 0.042
		fc.height = 0.11
		funnel.mesh = fc
		funnel.material_override = ThemeX.mat(Color("1a1a1a"), 0.5, 0.35)
		funnel.position = Vector3(0, 0.28, -0.15)
		root.add_child(funnel)
	return root

## Platform HTTP client — web uses window.fetch + polled result (reliable under Aseman proxy).
extends Node

signal response(ok: bool, path: String, data: Dictionary, err: String)

var base_url := ""
var user_id := "visitor"
var user_name := ""
var user_handle := ""
var _http: HTTPRequest
var _queue: Array = []
var _busy := false
var _inflight_path := ""
var _req_id := 0
var _poll_key := ""
var _poll_age := 0.0
const FETCH_TIMEOUT_S := 5.0


func _ready() -> void:
	if OS.has_feature("web"):
		_setup_js_fetch()
		set_process(true)
	else:
		_http = HTTPRequest.new()
		_http.timeout = 12.0
		add_child(_http)
		_http.request_completed.connect(_on_http_done)
		set_process(false)
	if base_url.is_empty():
		base_url = detect_base()


func _setup_js_fetch() -> void:
	JavaScriptBridge.eval("""
(function () {
  window.__railsFetch = function (id, url, method, body, headersJson) {
    var key = '__railsFetchResult_' + id;
    window[key] = null;
    var headers = {};
    try { headers = JSON.parse(headersJson || '{}'); } catch (e) {}
    var opts = { method: method || 'GET', headers: headers, credentials: 'same-origin' };
    if (body && method && method.toUpperCase() !== 'GET' && method.toUpperCase() !== 'HEAD') {
      opts.body = body;
    }
    var u = url;
    try {
      if (window.__asemanProxyFix) u = window.__asemanProxyFix(url);
    } catch (e1) {}
    fetch(u, opts).then(function (r) {
      return r.text().then(function (t) {
        window[key] = JSON.stringify({ ok: !!r.ok, code: r.status|0, body: t || '' });
      });
    }).catch(function (e) {
      window[key] = JSON.stringify({
        ok: false, code: 0, body: '', err: String(e && e.message ? e.message : e)
      });
    });
  };
})();
""", true)


func _process(delta: float) -> void:
	if _poll_key == "":
		return
	_poll_age += delta
	var raw = JavaScriptBridge.eval("window[%s]" % JSON.stringify(_poll_key), true)
	if raw != null and str(raw) != "" and str(raw) != "null" and str(raw) != "undefined":
		JavaScriptBridge.eval("window[%s] = null" % JSON.stringify(_poll_key), true)
		_poll_key = ""
		_poll_age = 0.0
		var parsed = JSON.parse_string(str(raw))
		var code := 0
		var body := ""
		var ok_http := false
		if typeof(parsed) == TYPE_DICTIONARY:
			code = int(parsed.get("code", 0))
			body = str(parsed.get("body", ""))
			ok_http = bool(parsed.get("ok", false))
		_finish(ok_http, code, body)
		return
	if _poll_age >= FETCH_TIMEOUT_S:
		JavaScriptBridge.eval("window[%s] = null" % JSON.stringify(_poll_key), true)
		_poll_key = ""
		_poll_age = 0.0
		_finish(false, 0, "")


static func detect_base() -> String:
	if OS.has_feature("web"):
		var from_q := _query_value("api_base")
		if from_q != "" and _looks_like_app_api(from_q):
			return _normalize_api_base(from_q)
		var path := str(JavaScriptBridge.eval("window.location.pathname", true))
		var idx := path.find("/games/")
		if idx >= 0:
			return _normalize_api_base(path.substr(0, idx))
		# Root-relative — Aseman proxy + __asemanProxyFix rewrite this.
		return "/api/"
	var env := OS.get_environment("RAILS_API").strip_edges()
	if env != "":
		return _normalize_api_base(env)
	return "http://127.0.0.1:8080/api/"


static func _looks_like_app_api(u: String) -> bool:
	var s := u.to_lower()
	return "/app/api" in s or s == "/api" or s.begins_with("/api/") or "/platforms/" in s


static func _query_value(key: String) -> String:
	if not OS.has_feature("web"):
		return ""
	var q = JavaScriptBridge.eval("window.location.search", true)
	if typeof(q) != TYPE_STRING:
		return ""
	for pair in str(q).trim_prefix("?").split("&", false):
		var kv := pair.split("=")
		if kv.size() == 2 and kv[0].uri_decode() == key:
			return kv[1].uri_decode()
	return ""


static func _normalize_api_base(raw: String) -> String:
	var u := raw.strip_edges()
	if u.is_empty():
		return "/api/"
	if u.begins_with("/") and not u.begins_with("//"):
		if not u.ends_with("/"):
			u += "/"
		if not u.ends_with("api/"):
			u = u.rstrip("/") + "/api/"
		return u
	if not u.ends_with("/"):
		u += "/"
	if not u.ends_with("api/"):
		u = u.rstrip("/") + "/api/"
	return u


func configure(p: Dictionary) -> void:
	if p.has("api_base") and str(p.api_base) != "":
		var raw := str(p.api_base)
		if _looks_like_app_api(raw):
			base_url = _normalize_api_base(raw)
		else:
			base_url = detect_base()
	if p.has("user_id") and str(p.user_id) != "":
		user_id = str(p.user_id)
	if p.has("player_name") and str(p.player_name) != "":
		user_name = str(p.player_name)
	if p.has("handle") and str(p.handle) != "":
		user_handle = str(p.handle)


func get_json(path: String) -> void:
	_enqueue("GET", path, "")


func post_json(path: String, body: Dictionary) -> void:
	_enqueue("POST", path, JSON.stringify(body))


func _enqueue(method: String, path: String, body: String) -> void:
	_queue.append({"method": method, "path": path, "body": body})
	_pump()


func _pump() -> void:
	if _busy or _queue.is_empty():
		return
	_busy = true
	var job: Dictionary = _queue.pop_front()
	_inflight_path = str(job.path)
	if base_url.is_empty():
		base_url = detect_base()
	var url := base_url.rstrip("/") + "/" + str(job.path).lstrip("/")
	var headers := {
		"Content-Type": "application/json",
		"Accept": "application/json",
		"X-Aseman-User": user_id,
		"X-Rails-User": user_id,
	}
	if user_name != "":
		headers["X-Aseman-Name"] = user_name
	if user_handle != "":
		headers["X-Aseman-Handle"] = user_handle

	if OS.has_feature("web"):
		_req_id += 1
		var id := _req_id
		_poll_key = "__railsFetchResult_%d" % id
		_poll_age = 0.0
		JavaScriptBridge.eval("window[%s] = null" % JSON.stringify(_poll_key), true)
		JavaScriptBridge.eval(
			"window.__railsFetch(%d, %s, %s, %s, %s)" % [
				id,
				JSON.stringify(url),
				JSON.stringify(str(job.method)),
				JSON.stringify(str(job.body)),
				JSON.stringify(JSON.stringify(headers)),
			],
			true
		)
		return

	var hdrs := PackedStringArray()
	for k in headers.keys():
		hdrs.append("%s: %s" % [k, headers[k]])
	var method := HTTPClient.METHOD_GET if str(job.method) == "GET" else HTTPClient.METHOD_POST
	var err := _http.request(url, hdrs, method, str(job.body))
	if err != OK:
		_busy = false
		var p := _inflight_path
		_inflight_path = ""
		response.emit(false, p, {}, "درخواست ارسال نشد")
		_pump()


func _on_http_done(_result: int, code: int, _headers: PackedStringArray, body: PackedByteArray) -> void:
	_finish(code >= 200 and code < 300, code, body.get_string_from_utf8())


func _finish(ok_http: bool, code: int, text: String) -> void:
	_busy = false
	var path := _inflight_path
	_inflight_path = ""
	var data: Dictionary = {}
	var parsed_ok := false
	if text != "":
		var parsed = JSON.parse_string(text)
		if typeof(parsed) == TYPE_DICTIONARY:
			data = parsed
			parsed_ok = true
	var ok := ok_http and parsed_ok
	var err := ""
	if not ok:
		if code == 0:
			err = "فعلاً به سرور وصل نیستیم. یکم بعد دوباره بیا."
		elif not parsed_ok and code >= 200 and code < 300:
			err = "آدرس API اشتباه است (پاسخ JSON نبود)."
		else:
			err = str(data.get("error", "خطای سرور (%d)" % code))
	response.emit(ok, path, data, err)
	_pump()

## Pure rules engine for Persian Rails Empire. No UI, no class_name, no autoload.
extends RefCounted

const COLORS := ["red", "blue", "green", "yellow", "black", "white", "orange", "purple"]
const SCORE_BY_LEN := {1: 1, 2: 2, 3: 4, 4: 7, 5: 10, 6: 15}
const LOCO := "locomotive"

var cities: Array = []
var routes: Array = []
var tickets_deck: Array = []
var culture: Array = []
var fa: Dictionary = {}

var players: Array = []  # {id, name, is_ai, color, wagons, score, hand, tickets, routes}
var face_up: Array = []
var deck: Array = []
var discard: Array = []
var ticket_pile: Array = []
var claimed: Dictionary = {}  # route_id -> player_index
var current: int = 0
var last_round: bool = false
var turns_left: int = -1
var over: bool = false
var move_count: int = 0
var started_at: int = 0
var rng: RandomNumberGenerator = RandomNumberGenerator.new()


func load_data(base: String = "res://arena/persian_rails/data") -> void:
	cities = _load_json(base + "/cities.json")
	routes = _load_json(base + "/routes.json")
	tickets_deck = _load_json(base + "/tickets.json")
	culture = _load_json(base + "/culture.json")
	fa = _load_json(base + "/fa.json")


func _load_json(path: String) -> Variant:
	var f := FileAccess.open(path, FileAccess.READ)
	if f == null:
		return [] if path.ends_with("fa.json") == false else {}
	var txt := f.get_as_text()
	var data = JSON.parse_string(txt)
	return data if data != null else ([] if not path.ends_with("fa.json") else {})


func start(human_name: String, ai_count: int = 1, wagons: int = 45, p_seed: int = 0) -> void:
	if p_seed != 0:
		rng.seed = p_seed
	else:
		rng.randomize()
	players.clear()
	claimed.clear()
	discard.clear()
	over = false
	last_round = false
	turns_left = -1
	move_count = 0
	started_at = Time.get_ticks_msec()
	current = 0
	var palette := ["#c4531f", "#156a87", "#3f8a55", "#9a2a48"]
	var names_ai := ["رخشا ریلی", "پارس‌لاین", "کویر اکسپرس", "خزر کارگو"]
	players.append(_new_player(0, human_name, false, palette[0], wagons))
	for i in range(clampi(ai_count, 1, 3)):
		players.append(_new_player(i + 1, names_ai[i], true, palette[(i + 1) % palette.size()], wagons))
	_build_deck()
	_shuffle(deck)
	ticket_pile = tickets_deck.duplicate(true)
	_shuffle(ticket_pile)
	face_up.clear()
	_refill_face_up()
	for p in players:
		for _i in range(4):
			p.hand.append(_draw_train())
		var offered := _deal_tickets(3)
		# keep 2 initially
		offered.sort_custom(func(a, b): return int(a.points) > int(b.points))
		p.tickets = [offered[0], offered[1]] if offered.size() >= 2 else offered
	# human starts


func _new_player(id: int, name: String, is_ai: bool, color: String, wagons: int) -> Dictionary:
	return {
		"id": id, "name": name, "is_ai": is_ai, "color": color,
		"wagons": wagons, "score": 0, "hand": [], "tickets": [], "routes": [],
	}


func _build_deck() -> void:
	deck.clear()
	for c in COLORS:
		for _i in range(12):
			deck.append(c)
	for _i in range(14):
		deck.append(LOCO)


func _shuffle(arr: Array) -> void:
	for i in range(arr.size() - 1, 0, -1):
		var j := rng.randi_range(0, i)
		var t = arr[i]
		arr[i] = arr[j]
		arr[j] = t


func _draw_train() -> String:
	if deck.is_empty():
		if discard.is_empty():
			return ""
		deck = discard.duplicate()
		discard.clear()
		_shuffle(deck)
	return String(deck.pop_back())


func _refill_face_up() -> void:
	while face_up.size() < 5:
		var c := _draw_train()
		if c == "":
			break
		face_up.append(c)
	_replace_triple_locos()


func _replace_triple_locos() -> void:
	var locos := 0
	for c in face_up:
		if c == LOCO:
			locos += 1
	if locos >= 3:
		for c in face_up:
			discard.append(c)
		face_up.clear()
		_refill_face_up()


func _deal_tickets(n: int) -> Array:
	var out: Array = []
	for _i in range(n):
		if ticket_pile.is_empty():
			break
		out.append(ticket_pile.pop_back())
	return out


func route_by_id(id: String) -> Dictionary:
	for r in routes:
		if str(r.id) == id:
			return r
	return {}


func city_by_id(id: String) -> Dictionary:
	for c in cities:
		if str(c.id) == id:
			return c
	return {}


func cost_for_route(route: Dictionary) -> int:
	var n := int(route.get("length", 1))
	var t := str(route.get("terrain", "plain"))
	if t == "mountain" or t == "bridge":
		n += 1
	return n


func route_score(route: Dictionary) -> int:
	var L := int(route.get("length", 1))
	return int(SCORE_BY_LEN.get(L, L * 2))


func can_afford(hand: Array, route: Dictionary) -> Dictionary:
	## Returns {ok, pay: Array of colors to remove} or {ok:false}
	var need := cost_for_route(route)
	var color := str(route.get("color", "gray"))
	var counts := {}
	for c in hand:
		counts[c] = int(counts.get(c, 0)) + 1
	var locos := int(counts.get(LOCO, 0))
	if color == "gray":
		# pay with any single color + locos
		var best := ""
		var best_have := -1
		for col in COLORS:
			var have := int(counts.get(col, 0))
			if have > best_have:
				best_have = have
				best = col
		var use_col := mini(best_have, need)
		var use_loco := need - use_col
		if use_loco > locos:
			return {"ok": false}
		var pay: Array = []
		for _i in range(use_col):
			pay.append(best)
		for _i in range(use_loco):
			pay.append(LOCO)
		return {"ok": true, "pay": pay}
	var have := int(counts.get(color, 0))
	var use_col := mini(have, need)
	var use_loco := need - use_col
	if use_loco > locos:
		return {"ok": false}
	var pay2: Array = []
	for _i in range(use_col):
		pay2.append(color)
	for _i in range(use_loco):
		pay2.append(LOCO)
	return {"ok": true, "pay": pay2}


func remove_from_hand(hand: Array, pay: Array) -> void:
	for c in pay:
		var i := hand.find(c)
		if i >= 0:
			hand.remove_at(i)
			discard.append(c)


func legal_actions(pi: int = -1) -> Array:
	if over:
		return []
	if pi < 0:
		pi = current
	var p: Dictionary = players[pi]
	var acts: Array = [{"type": "draw_trains"}]
	for r in routes:
		var rid := str(r.id)
		if claimed.has(rid):
			continue
		if int(p.wagons) < cost_for_route(r):
			continue
		var aff := can_afford(p.hand, r)
		if aff.get("ok", false):
			acts.append({"type": "claim", "route": rid, "pay": aff.pay})
	if not ticket_pile.is_empty():
		acts.append({"type": "draw_tickets"})
	return acts


func apply(action: Dictionary, pi: int = -1) -> Dictionary:
	## Apply an action for the current (or given) player. Returns event dict.
	if over:
		return {"ok": false, "error": "game_over"}
	if pi < 0:
		pi = current
	if pi != current:
		return {"ok": false, "error": "not_your_turn"}
	var p: Dictionary = players[pi]
	var typ := str(action.get("type", ""))
	var ev := {"ok": true, "type": "move", "player": pi, "action": typ, "move": move_count}
	match typ:
		"draw_trains":
			var picks: Array = action.get("picks", [])
			var got: Array = []
			if picks.is_empty():
				# default: two from deck
				for _i in range(2):
					var c := _draw_train()
					if c != "":
						p.hand.append(c)
						got.append(c)
			else:
				var taken := 0
				for pick in picks:
					if taken >= 2:
						break
					if str(pick) == "deck":
						var c2 := _draw_train()
						if c2 != "":
							p.hand.append(c2)
							got.append(c2)
							taken += 1
					else:
						var idx := int(pick)
						if idx < 0 or idx >= face_up.size():
							continue
						var card := String(face_up[idx])
						# locomotive face-up costs the whole draw
						face_up.remove_at(idx)
						p.hand.append(card)
						got.append(card)
						taken += 1
						if card == LOCO:
							taken = 2
						_refill_face_up()
				while taken < 2:
					var c3 := _draw_train()
					if c3 == "":
						break
					p.hand.append(c3)
					got.append(c3)
					taken += 1
			ev["cards"] = got
		"claim":
			var rid := str(action.get("route", ""))
			var route := route_by_id(rid)
			if route.is_empty() or claimed.has(rid):
				return {"ok": false, "error": "route_unavailable"}
			var need := cost_for_route(route)
			if int(p.wagons) < need:
				return {"ok": false, "error": "no_wagons"}
			var aff := can_afford(p.hand, route)
			if not aff.get("ok", false):
				return {"ok": false, "error": "need_cards"}
			var pay: Array = action.get("pay", aff.pay)
			remove_from_hand(p.hand, pay)
			p.wagons = int(p.wagons) - need
			p.score = int(p.score) + route_score(route)
			p.routes.append(rid)
			claimed[rid] = pi
			ev["route"] = rid
			ev["points"] = route_score(route)
			if int(p.wagons) <= 2 and not last_round:
				last_round = true
				turns_left = players.size()
		"draw_tickets":
			var offered := _deal_tickets(3)
			var keep: Array = action.get("keep", [])
			if keep.is_empty():
				# keep the highest-value one
				offered.sort_custom(func(a, b): return int(a.points) > int(b.points))
				keep = [offered[0]] if offered.size() else []
				for i in range(1, offered.size()):
					ticket_pile.append(offered[i])
			else:
				var keep_ids := {}
				for k in keep:
					keep_ids[str(k)] = true
				var kept: Array = []
				for t in offered:
					if keep_ids.has(str(t.id)):
						kept.append(t)
					else:
						ticket_pile.append(t)
				if kept.is_empty() and offered.size():
					kept.append(offered[0])
				keep = kept
			for t in keep:
				p.tickets.append(t)
			ev["tickets"] = keep.size()
		_:
			return {"ok": false, "error": "bad_action"}
	move_count += 1
	_advance_turn()
	ev["next"] = current
	ev["over"] = over
	return ev


func _advance_turn() -> void:
	if last_round:
		turns_left -= 1
		if turns_left <= 0:
			_finalize()
			return
	current = (current + 1) % players.size()


func connected(pi: int, a: String, b: String) -> bool:
	var mine: Dictionary = {}
	for rid in players[pi].routes:
		mine[rid] = true
	var graph: Dictionary = {}
	for r in routes:
		if not mine.has(str(r.id)):
			continue
		var u := str(r.from)
		var v := str(r.to)
		if not graph.has(u):
			graph[u] = []
		if not graph.has(v):
			graph[v] = []
		graph[u].append(v)
		graph[v].append(u)
	if not graph.has(a):
		return false
	var seen := {}
	var stack := [a]
	while stack.size():
		var n = stack.pop_back()
		if n == b:
			return true
		if seen.has(n):
			continue
		seen[n] = true
		for m in graph.get(n, []):
			if not seen.has(m):
				stack.append(m)
	return false


func longest_path_len(pi: int) -> int:
	var mine: Dictionary = {}
	for rid in players[pi].routes:
		mine[rid] = true
	var graph: Dictionary = {}
	var edge_w: Dictionary = {}
	for r in routes:
		if not mine.has(str(r.id)):
			continue
		var u := str(r.from)
		var v := str(r.to)
		var w := int(r.length)
		if not graph.has(u):
			graph[u] = []
		if not graph.has(v):
			graph[v] = []
		graph[u].append(v)
		graph[v].append(u)
		edge_w[u + ">" + v] = w
		edge_w[v + ">" + u] = w
	var best := 0
	for start in graph.keys():
		best = maxi(best, _dfs_longest(start, graph, edge_w, {}, 0))
	return best


func _dfs_longest(node: String, graph: Dictionary, edge_w: Dictionary, used: Dictionary, acc: int) -> int:
	var best := acc
	for nxt_v in graph.get(node, []):
		var nxt: String = str(nxt_v)
		var e1: String = node + ">" + nxt
		var e2: String = nxt + ">" + node
		if used.has(e1) or used.has(e2):
			continue
		used[e1] = true
		used[e2] = true
		best = maxi(best, _dfs_longest(nxt, graph, edge_w, used, acc + int(edge_w.get(e1, 1))))
		used.erase(e1)
		used.erase(e2)
	return best


func _finalize() -> void:
	over = true
	var lengths: Array = []
	for i in range(players.size()):
		lengths.append(longest_path_len(i))
	var max_len := 0
	for L in lengths:
		max_len = maxi(max_len, int(L))
	for i in range(players.size()):
		var p: Dictionary = players[i]
		for t in p.tickets:
			if connected(i, str(t.from), str(t.to)):
				p.score = int(p.score) + int(t.points)
			else:
				p.score = int(p.score) - int(t.points)
		if int(lengths[i]) == max_len and max_len > 0:
			p.score = int(p.score) + 10
		players[i] = p


func final_result() -> Dictionary:
	var human: Dictionary = players[0] as Dictionary
	var best_ai := -9999
	for i in range(1, players.size()):
		best_ai = maxi(best_ai, int(players[i].score))
	var hs := int(human.score)
	var outcome := "draw"
	if hs > best_ai:
		outcome = "win"
	elif hs < best_ai:
		outcome = "loss"
	return {
		"type": "result",
		"game": "persian-rails",
		"outcome": outcome,
		"score": hs,
		"ai_score": best_ai,
		"duration_s": int((Time.get_ticks_msec() - started_at) / 1000.0),
		"moves": move_count,
		"players": players.map(func(p): return {"name": p.name, "score": p.score, "is_ai": p.is_ai}),
	}


func snapshot() -> Dictionary:
	return {
		"current": current,
		"over": over,
		"last_round": last_round,
		"face_up": face_up.duplicate(),
		"claimed": claimed.duplicate(),
		"players": players.duplicate(true),
		"move_count": move_count,
	}

## Full-app Godot shell — replaces Flutter/Elpian 5-tab UI with HUD design language.
extends Control

signal arena_event(json: String)

const Fonts = preload("res://arena/persian_rails/fonts.gd")
const ThemeX = preload("res://arena/persian_rails/theme.gd")
const Assets = preload("res://arena/persian_rails/assets.gd")
const Ui = preload("res://arena/persian_rails/ui_kit.gd")
const PlatformApi = preload("res://arena/persian_rails/platform_api.gd")
const ArenaScene = preload("res://arena/persian_rails/main.tscn")

const TABS := [
	{"id": "home", "label": "خانه"},
	{"id": "play", "label": "بازی"},
	{"id": "atlas", "label": "اطلس"},
	{"id": "ranks", "label": "افتخار"},
	{"id": "rules", "label": "قوانین"},
]

var _api: Node
var _d: Dictionary = {}
var _tab := "home"
var _cfg: Dictionary = {}
var _fa: Dictionary = {}
var _booted := false
var _boot_error := ""
var _atlas = null
var _atlas_error := ""
var _board = null
var _board_error := ""
var _rules = null
var _rules_error := ""
var _play_level := 2
var _play_ai := 1
var _launching := false
var _play_error := ""
var _match: Dictionary = {}
var _outcome: Dictionary = {}
var _result_server: Dictionary = {}
var _submitting := false
var _pending := ""

var _root: Control
var _chrome: Control
var _scroll: ScrollContainer
var _body: VBoxContainer
var _nav: PanelContainer
var _nav_row: HBoxContainer
var _arena: Node = null
var _play_overlay: CanvasLayer
var _leave_btn: Button
var _result_layer: CanvasLayer


func _ready() -> void:
	layout_direction = Control.LAYOUT_DIRECTION_RTL
	set_anchors_preset(Control.PRESET_FULL_RECT)
	_install_font()
	_api = PlatformApi.new()
	_api.name = "PlatformApi"
	add_child(_api)
	_api.response.connect(_on_api)
	_api.configure(_params_from_page())
	_build()
	get_viewport().size_changed.connect(_on_resize)
	_on_resize()
	_boot()
	# Direct match deep-link (legacy web embed with query params).
	var q := _params_from_page()
	if q.has("level") and (q.has("token") or q.has("match") or bool(q.get("autostart", false))):
		call_deferred("_autostart_match", q)


## Arena contract — host may call these on the pack root (shell).
## Bootstrap params (api_base / player_name) only configure the shell.
## A real match needs level/token/autostart (or the in-shell Play tab).
func arena_start(p: Dictionary = {}) -> void:
	_api.configure(p)
	var wants_match := p.has("level") or p.has("token") or p.has("match") or bool(p.get("autostart", false))
	if wants_match:
		_begin_arena(p)
	elif not _booted:
		_boot()


func arena_stop() -> void:
	_end_arena(false)


func arena_state() -> Dictionary:
	if _arena and _arena.has_method("arena_state"):
		return _arena.arena_state()
	return {}


func _install_font() -> void:
	var font := Fonts.regular()
	if font == null:
		return
	var theme := Theme.new()
	theme.default_font = font
	theme.default_font_size = 22
	theme.set_font("font", "Label", font)
	theme.set_font("font", "Button", Fonts.bold() if Fonts.bold() else font)
	get_tree().root.theme = theme


func _params_from_page() -> Dictionary:
	var out := {}
	if not OS.has_feature("web"):
		return out
	var q = JavaScriptBridge.eval("window.location.search", true)
	if typeof(q) != TYPE_STRING:
		return out
	for pair in str(q).trim_prefix("?").split("&", false):
		var kv := pair.split("=")
		if kv.size() == 2:
			out[kv[0].uri_decode()] = kv[1].uri_decode()
	for k in ["level", "ai_count", "wagons"]:
		if out.has(k):
			out[k] = int(out[k])
	# Always resolve API against the platform app, even without query params.
	if not out.has("api_base"):
		var detected := PlatformApi.detect_base()
		if detected != "":
			out["api_base"] = detected
	return out


func _build() -> void:
	_root = Control.new()
	_root.set_anchors_preset(Control.PRESET_FULL_RECT)
	_root.layout_direction = Control.LAYOUT_DIRECTION_RTL
	add_child(_root)

	var bg := Control.new()
	bg.set_anchors_preset(Control.PRESET_FULL_RECT)
	bg.mouse_filter = Control.MOUSE_FILTER_IGNORE
	_root.add_child(bg)
	Ui.wood_backdrop(bg)

	_chrome = Control.new()
	_chrome.set_anchors_preset(Control.PRESET_FULL_RECT)
	_root.add_child(_chrome)

	_scroll = ScrollContainer.new()
	_scroll.set_anchors_preset(Control.PRESET_FULL_RECT)
	_scroll.horizontal_scroll_mode = ScrollContainer.SCROLL_MODE_DISABLED
	_chrome.add_child(_scroll)

	_body = VBoxContainer.new()
	_body.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	_body.add_theme_constant_override("separation", 12)
	_scroll.add_child(_body)

	_nav = Ui.framed("top", 10.0, 1.0)
	_nav.set_anchors_preset(Control.PRESET_BOTTOM_WIDE)
	_chrome.add_child(_nav)
	_nav_row = HBoxContainer.new()
	_nav_row.add_theme_constant_override("separation", 0)
	_nav_row.alignment = BoxContainer.ALIGNMENT_CENTER
	_nav.add_child(_nav_row)

	# No floating web/leave shortcut over the board — exit lives in the HUD top bar.
	_play_overlay = CanvasLayer.new()
	_play_overlay.layer = 40
	_play_overlay.visible = false
	add_child(_play_overlay)
	_leave_btn = null

	_result_layer = CanvasLayer.new()
	_result_layer.layer = 50
	_result_layer.visible = false
	add_child(_result_layer)


func _on_resize() -> void:
	var vp := get_viewport().get_visible_rect().size
	_d = Ui.density_for(vp)
	var s: float = float(_d.scale)
	var pad: float = float(_d.pad)
	var nav_h: float = float(_d.get("shell_nav_h", clampf(72.0 * s, 64.0, 88.0)))
	_nav.offset_left = 6
	_nav.offset_right = -6
	_nav.offset_top = -nav_h - 6.0
	_nav.offset_bottom = -6
	_nav.add_theme_stylebox_override("panel", Assets.style_tex("panel_top.png", pad * 0.7, 32.0 * minf(s, 2.0)))
	_scroll.offset_left = 0
	_scroll.offset_right = 0
	_scroll.offset_top = 0
	_scroll.offset_bottom = -nav_h - 8.0
	# Full-bleed shell content — never pinch to a narrow 420px column on phones.
	_body.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	_body.custom_minimum_size = Vector2(maxf(280.0, vp.x - 4.0), 0)
	_rebuild_nav()
	_rebuild_body()


func _sf(key: String, fallback_key: String = "font_body") -> int:
	return int(_d.get(key, _d.get(fallback_key, 16)))


func _btn_h() -> float:
	return float(_d.get("shell_btn_h", _d.get("btn_h", 54.0)))


func _t(key: String, fallback: String = "") -> String:
	return str(_fa.get(key, fallback if fallback else key))


func _boot() -> void:
	# Never block the 5-tab shell on network — show UI immediately, refresh if API answers.
	_boot_error = ""
	_apply_offline_fallback()
	_booted = true
	_pending = "me"
	_rebuild_body()
	_api.get_json("me")


func _on_api(ok: bool, path: String, data: Dictionary, err: String) -> void:
	var p := path
	if p.begins_with("/"):
		p = p.substr(1)
	if p == "me" or (_pending == "me" and p.ends_with("me")):
		_pending = ""
		if ok and data.has("me"):
			_cfg = data
			_fa = data.get("fa", {})
			if typeof(_fa) != TYPE_DICTIONARY:
				_fa = {}
			_booted = true
			_boot_error = ""
			var me = data.get("me", {})
			if typeof(me) == TYPE_DICTIONARY:
				_api.user_name = str(me.get("name", _api.user_name))
		# Soft-fail: keep offline shell if me fails; do not trap user on a spinner.
		_rebuild_body()
		return
	if p == "atlas" or p.ends_with("atlas"):
		if ok:
			_atlas = data
			_atlas_error = ""
		else:
			_atlas = _local_atlas()
			_atlas_error = "" if _atlas != null else err
		_rebuild_body()
		return
	if p == "leaderboard" or p.ends_with("leaderboard"):
		if ok:
			_board = data
			_board_error = ""
		else:
			# Empty board is still usable; keep a soft note for retry.
			_board = {"board": [], "offline": true, "error": err}
			_board_error = ""
		_rebuild_body()
		return
	if p == "rules" or p.ends_with("rules"):
		if ok:
			_rules = data
			_rules_error = ""
		else:
			_rules = _local_rules()
			_rules_error = "" if _rules != null else err
		_rebuild_body()
		return
	if p == "matches" or (p.begins_with("matches") and not p.ends_with("/result")):
		_launching = false
		var params := _local_match_params()
		if ok:
			_play_error = ""
			_match = data.get("match", {})
			var launch: Dictionary = data.get("launch", {})
			var lp: Dictionary = launch.get("params", {})
			if typeof(lp) == TYPE_DICTIONARY:
				for k in lp.keys():
					params[k] = lp[k]
			_begin_arena(params)
		else:
			# Offline practice — still open the board with HUD chrome.
			_play_error = ""
			_match = {}
			_begin_arena(params)
		return
	if p.ends_with("/result"):
		_submitting = false
		if ok:
			_result_server = data
		else:
			_play_error = err
		_show_result_overlay()
		return


func _apply_offline_fallback() -> void:
	# Local pack still works without the platform server.
	_booted = true
	var fa_res = _load_json("res://arena/persian_rails/data/fa.json")
	if typeof(fa_res) == TYPE_DICTIONARY:
		_fa = fa_res
	_cfg = {
		"product": _t("product", "امپراتوری راه‌آهن پارس"),
		"fa": _fa,
		"me": {"name": "مهمان", "rating": 1200, "progress": {"level": 1}},
		"game": {
			"title": _t("product", "امپراتوری راه‌آهن پارس"),
			"tagline": _t("tagline", "شهرهای ایران را با لبخند به هم وصل کن"),
			"settings": {"level": {"default": 2}, "ai_count": {"default": 1}},
		},
	}
	_boot_error = ""


func _load_json(path: String):
	if not ResourceLoader.exists(path) and not FileAccess.file_exists(path):
		return null
	var f := FileAccess.open(path, FileAccess.READ)
	if f == null:
		return null
	return JSON.parse_string(f.get_as_text())


func _local_atlas():
	var culture = _load_json("res://arena/persian_rails/data/culture.json")
	if typeof(culture) != TYPE_ARRAY:
		return null
	return {"culture": culture, "fa": _fa, "local": true}


func _local_rules() -> Dictionary:
	return {
		"title": "قوانین خودمونی",
		"turns": [
			"تو هر نوبت یکی از این سه کار رو انجام بده:",
			"۱) دو کارت رنگی بردار (از روی میز یا از دسته).",
			"۲) یک مسیر آزاد بساز و به تعداد طولش کارت بده.",
			"۳) قرارداد مقصد بردار و حداقل یکی‌ش رو نگه دار.",
		],
		"end": "وقتی واگن‌هات به ۲ یا کمتر رسید، همه یک نوبت آخر دارن.",
		"note": _t("scenario_note", "بعضی مسیرها سناریویی‌ان و با برچسب مشخص شدن."),
		"local": true,
	}


func _set_tab(id: String) -> void:
	_tab = id
	if id == "atlas" and _atlas == null and _atlas_error == "":
		_load_atlas()
	elif id == "ranks" and _board == null and _board_error == "":
		_load_board()
	elif id == "rules" and _rules == null and _rules_error == "":
		_load_rules()
	_rebuild_nav()
	_rebuild_body()


func _load_atlas() -> void:
	# Show local culture immediately, then refresh from API when available.
	_atlas = _local_atlas()
	_atlas_error = ""
	_rebuild_body()
	_api.get_json("atlas")


func _load_board() -> void:
	_board = null
	_board_error = ""
	_rebuild_body()
	_api.get_json("leaderboard")


func _load_rules() -> void:
	_rules = _local_rules()
	_rules_error = ""
	_rebuild_body()
	_api.get_json("rules")


func _local_match_params() -> Dictionary:
	var name := "تو"
	if typeof(_cfg.get("me", null)) == TYPE_DICTIONARY:
		name = str((_cfg.me as Dictionary).get("name", "تو"))
	return {
		"level": _play_level,
		"ai_count": _play_ai,
		"player_name": name,
		"wagons": 45,
	}


func _start_match() -> void:
	_launching = true
	_play_error = ""
	_outcome = {}
	_result_server = {}
	_rebuild_body()
	_api.post_json("matches", _local_match_params())


func _autostart_match(q: Dictionary) -> void:
	_play_level = int(q.get("level", 2))
	_play_ai = int(q.get("ai_count", 1))
	var params := q.duplicate()
	params["level"] = _play_level
	params["ai_count"] = _play_ai
	_begin_arena(params)


func _begin_arena(params: Dictionary) -> void:
	_end_arena(false)
	_tab = "play"
	_chrome.visible = false
	# Let the Node3D arena receive picks — shell Control must not eat input.
	mouse_filter = Control.MOUSE_FILTER_IGNORE
	if _root:
		_root.mouse_filter = Control.MOUSE_FILTER_IGNORE
	_play_overlay.visible = false
	_result_layer.visible = false
	_arena = ArenaScene.instantiate()
	_arena.name = "Arena"
	add_child(_arena)
	if _arena.has_signal("arena_event"):
		_arena.arena_event.connect(_on_arena_event)
	# Shell drives start; arena is not the current_scene so it won't auto-start.
	if _arena.has_method("arena_start"):
		_arena.call_deferred("arena_start", params)
	_emit({"type": "shell_playing", "game": "persian-rails"})


func _end_arena(to_lobby: bool) -> void:
	if _arena:
		if _arena.has_method("arena_stop"):
			_arena.arena_stop()
		_arena.queue_free()
		_arena = null
	_play_overlay.visible = false
	_result_layer.visible = false
	_chrome.visible = true
	mouse_filter = Control.MOUSE_FILTER_STOP
	if _root:
		_root.mouse_filter = Control.MOUSE_FILTER_STOP
	if to_lobby:
		_tab = "play"
		_match = {}
		_outcome = {}
		_result_server = {}
		_rebuild_nav()
		_rebuild_body()


func _on_arena_event(json: String) -> void:
	arena_event.emit(json)
	var d = JSON.parse_string(json)
	if typeof(d) != TYPE_DICTIONARY:
		return
	if d.has("arena") and typeof(d.arena) == TYPE_DICTIONARY:
		d = d.arena
	var kind := str(d.get("type", ""))
	if kind == "leave":
		_end_arena(true)
		return
	if kind != "result":
		return
	if _submitting or not _outcome.is_empty():
		return
	_outcome = d
	var token := str(_match.get("token", ""))
	if token == "" and _arena and _arena.get("params") != null:
		token = str((_arena.params as Dictionary).get("token", ""))
	if token != "":
		_submitting = true
		var body := {}
		for k in d.keys():
			if typeof(d[k]) != TYPE_DICTIONARY and typeof(d[k]) != TYPE_ARRAY and str(k) != "id":
				body[k] = d[k]
		_api.post_json("matches/%s/result" % token, body)
	else:
		_show_result_overlay()


func _show_result_overlay() -> void:
	for c in _result_layer.get_children():
		c.queue_free()
	_result_layer.visible = true
	var dim := ColorRect.new()
	dim.color = Color(0.05, 0.02, 0.01, 0.58)
	dim.set_anchors_preset(Control.PRESET_FULL_RECT)
	_result_layer.add_child(dim)
	var center := CenterContainer.new()
	center.set_anchors_preset(Control.PRESET_FULL_RECT)
	_result_layer.add_child(center)
	var card := Ui.framed("card", 18.0 * minf(float(_d.get("scale", 1.0)), 2.0), float(_d.get("scale", 1.0)))
	card.custom_minimum_size = Vector2(minf(get_viewport().get_visible_rect().size.x - 24.0, 400.0), 0)
	center.add_child(card)
	var col := VBoxContainer.new()
	col.add_theme_constant_override("separation", 12)
	card.add_child(col)
	var outcome := str(_outcome.get("outcome", "draw"))
	var head := "آفرین، بردی!" if outcome == "win" else ("مساوی شد!" if outcome == "draw" else "این‌بار نشد؛ دوباره بزن!")
	var title := Ui.body_label(head, int(_d.get("font_title", 18)) + 2, ThemeX.TEAL_DEEP if outcome == "win" else ThemeX.CLAY, true)
	Fonts.apply(title, int(_d.get("font_title", 18)) + 2, true)
	col.add_child(title)
	if not _result_server.is_empty():
		col.add_child(Ui.body_label(
			"رتبه: %s → %s · تجربه: %s" % [
				str(_result_server.get("rating_before", "?")),
				str(_result_server.get("rating_after", "?")),
				str(_result_server.get("xp", "?")),
			],
			int(_d.get("font_body", 15)), ThemeX.INK, true
		))
	else:
		col.add_child(Ui.body_label(
			"تو %d  —  حریف %d" % [int(_outcome.get("score", 0)), int(_outcome.get("ai_score", 0))],
			int(_d.get("font_body", 15)), ThemeX.INK, true
		))
	var again := Ui.make_btn("یه دست دیگه", "primary", float(_d.scale), float(_d.btn_h), int(_d.font_btn))
	again.pressed.connect(func():
		_result_layer.visible = false
		_outcome = {}
		_result_server = {}
		_start_match()
	)
	col.add_child(again)
	var done := Ui.make_btn("تمام", "secondary", float(_d.scale), float(_d.btn_h), int(_d.font_btn))
	done.pressed.connect(func():
		_end_arena(true)
		_tab = "home"
		_rebuild_nav()
		_rebuild_body()
	)
	col.add_child(done)


func _emit(obj: Dictionary) -> void:
	var json := JSON.stringify(obj)
	arena_event.emit(json)
	if OS.has_feature("web"):
		JavaScriptBridge.eval("window.parent && window.parent.postMessage({arena: %s}, '*')" % json, true)


func _clear(node: Node) -> void:
	for c in node.get_children():
		c.queue_free()


func _rebuild_nav() -> void:
	_clear(_nav_row)
	var s: float = float(_d.get("scale", 1.0))
	var nav_font := _sf("shell_nav", "font_chip")
	var nav_h: float = float(_d.get("shell_nav_h", 72.0))
	var sel := _tab
	for tab in TABS:
		var id: String = tab.id
		var cell := Button.new()
		cell.text = "%s\n%s" % [_nav_glyph(id), tab.label]
		cell.focus_mode = Control.FOCUS_NONE
		cell.size_flags_horizontal = Control.SIZE_EXPAND_FILL
		cell.flat = true
		cell.alignment = HORIZONTAL_ALIGNMENT_CENTER
		var on := id == sel
		Fonts.apply(cell, nav_font + (1 if on else 0), on)
		cell.add_theme_color_override("font_color", ThemeX.GOLD_SOFT if on else ThemeX.CREAM)
		cell.add_theme_color_override("font_hover_color", ThemeX.GOLD_SOFT)
		cell.add_theme_color_override("font_pressed_color", ThemeX.GOLD)
		cell.add_theme_color_override("font_outline_color", ThemeX.WOOD_DARK)
		cell.add_theme_constant_override("outline_size", 3)
		cell.custom_minimum_size = Vector2(0, nav_h - 16.0)
		var empty := StyleBoxEmpty.new()
		cell.add_theme_stylebox_override("normal", empty)
		cell.add_theme_stylebox_override("hover", empty)
		cell.add_theme_stylebox_override("pressed", empty)
		cell.add_theme_stylebox_override("focus", empty)
		cell.pressed.connect(_set_tab.bind(id))
		_nav_row.add_child(cell)


func _nav_glyph(id: String) -> String:
	match id:
		"home":
			return "⌂"
		"play":
			return "▣"
		"atlas":
			return "◎"
		"ranks":
			return "★"
		"rules":
			return "☰"
		_:
			return "·"


func _page_pad() -> float:
	var dpr := float(_d.get("dpr", 1.0))
	return (12.0 if bool(_d.get("compact", true)) else 16.0) * maxf(dpr * float(_d.get("scale", 1.0)), 1.0)


func _mk_btn(text: String, kind: String) -> Button:
	return Ui.make_btn(text, kind, float(_d.get("scale", 1.0)), _btn_h(), _sf("shell_btn", "font_btn"))


func _rebuild_body() -> void:
	_clear(_body)
	var margin := MarginContainer.new()
	var p := _page_pad()
	margin.add_theme_constant_override("margin_left", int(p))
	margin.add_theme_constant_override("margin_right", int(p))
	margin.add_theme_constant_override("margin_top", int(p))
	margin.add_theme_constant_override("margin_bottom", int(p + 20))
	margin.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	_body.add_child(margin)
	var col := VBoxContainer.new()
	col.add_theme_constant_override("separation", 12)
	col.size_flags_horizontal = Control.SIZE_EXPAND_FILL
	margin.add_child(col)

	if not _booted:
		if _boot_error != "":
			_fill_problem(col, _boot_error, _boot)
		else:
			_fill_loading(col, "سلام! داریم ایستگاه رو باز می‌کنیم…")
		return

	match _tab:
		"play":
			_fill_play(col)
		"atlas":
			_fill_atlas(col)
		"ranks":
			_fill_ranks(col)
		"rules":
			_fill_rules(col)
		_:
			_fill_home(col)


func _fill_loading(col: VBoxContainer, msg: String) -> void:
	var panel := Ui.framed("fantasy", float(_d.pad), float(_d.scale))
	col.add_child(panel)
	var inner := VBoxContainer.new()
	inner.add_theme_constant_override("separation", 14)
	inner.alignment = BoxContainer.ALIGNMENT_CENTER
	panel.add_child(inner)
	var spin := ProgressBar.new()
	spin.show_percentage = false
	spin.indeterminate = true
	spin.custom_minimum_size = Vector2(0, 12)
	inner.add_child(spin)
	inner.add_child(Ui.body_label(msg, _sf("shell_body"), Color("5a4336"), true))


func _fill_problem(col: VBoxContainer, text: String, retry: Callable) -> void:
	var card := Ui.framed("card", float(_d.pad), float(_d.scale))
	col.add_child(card)
	var inner := VBoxContainer.new()
	inner.add_theme_constant_override("separation", 12)
	card.add_child(inner)
	inner.add_child(Ui.callout("ای وای!", text, ThemeX.CLAY, _sf("shell_title"), _sf("shell_body")))
	var b := _mk_btn("دوباره امتحان کنیم", "accent")
	b.pressed.connect(retry)
	inner.add_child(b)


func _top_title(col: VBoxContainer, title: String, subtitle: String = "") -> void:
	var top := Ui.framed("top", float(_d.pad), float(_d.scale))
	col.add_child(top)
	var inner := VBoxContainer.new()
	inner.add_theme_constant_override("separation", 6)
	top.add_child(inner)
	inner.add_child(Ui.cream_label(title, _sf("shell_title") + 2))
	if subtitle != "":
		inner.add_child(Ui.gold_label(subtitle, _sf("shell_body")))


func _fill_home(col: VBoxContainer) -> void:
	_top_title(col, _t("product", "امپراتوری راه‌آهن پارس"), _t("tagline", "شهرهای ایران را با لبخند به هم وصل کن"))
	var panel := Ui.framed("fantasy", float(_d.pad), float(_d.scale))
	col.add_child(panel)
	var inner := VBoxContainer.new()
	inner.add_theme_constant_override("separation", 12)
	panel.add_child(inner)
